export const itemGlyph = b => { const [k, a, c, e] = String(b).split(':'), key = k === 'a' ? `a:${a}:${e}` : `${k}:${a}`, v = ITEM_ICONS[key] ?? OWN_ICONS[key]; return Array.isArray(v) ? v[+c] : v; };
